    #[doc = "Inject Time Request"]
    pub mod inject_time_request {
        use crate::{Endian, Error, TlvBuf, TlvReader, TlvWriter};
        use alloc::string::String;
        use alloc::vec::Vec;
        pub const MESSAGE_ID: u16 = 40;
        #[derive(Debug, Clone, PartialEq, Default)]
        pub struct Indication {}
        impl Indication {
            pub fn to_tlvs(&self) -> Result<Vec<TlvBuf>, Error> {
                Ok(Vec::new())
            }
            pub fn from_tlvs(_tlvs: &[TlvBuf]) -> Result<Self, Error> {
                Ok(Self::default())
            }
        }
        #[derive(Debug, Clone, PartialEq, Default)]
        pub struct TimeServerInfo {
            pub delay_threshold: u32,
            pub time_server_list: Vec<String>,
        }
        impl TimeServerInfo {
            pub fn encode_to(&self, writer: &mut TlvWriter) -> Result<(), Error> {
                writer.write_u32(*&self.delay_threshold, Endian::Little);
                writer.write_u8(
                    u8::try_from((&self.time_server_list).len()).map_err(|_| Error::TooLong)?,
                );
                for item in &self.time_server_list {
                    writer.write_string(item, 1, None)?;
                }
                Ok(())
            }
            pub fn decode_from(reader: &mut TlvReader<'_>) -> Result<Self, Error> {
                let mut out = Self::default();
                out.delay_threshold = reader.read_u32(Endian::Little)?;
                let count = reader.read_u8()? as usize;
                let mut items = Vec::with_capacity(count.min(256));
                for _ in 0..count {
                    items.push(reader.read_string(1, 0)?);
                }
                out.time_server_list = items;
                Ok(out)
            }
        }
    }
